mapper.select:
SELECT 
FROM material m
LEFT JOIN position p ON p.id = m.position_id AND p.deleted = 0

    m.deleted = 0

        AND EXISTS (
            SELECT 1 FROM dept_position dp
            WHERE dp.position_id = m.position_id AND dp.status = 1 AND dp.dept_id = #{scopeDeptId}
        )


        AND m.material_name LIKE CONCAT('%', #{materialName}, '%')


        AND m.material_type = #{materialType}


        AND m.position_id = #{positionId}


        AND m.status = #{status}


ORDER BY m.status ASC, m.create_time DESC, m.id DESC
